{
  "verses": [
    {
      "chapter": 25,
      "text_ar": "وقال آدم لشيث: «اسمع يا بني شيث، لأقص عليك ما سمعتُه و",
      "verse": 1
    },
    {
      "chapter": 25,
      "text_ar": "رأيتُه بعد أن طُردتُ أنا وأمك من الفردوس. وعندما كنا نصلي، أتى",
      "verse": 2
    },
    {
      "chapter": 25,
      "text_ar": "إليّ رئيس الملائكة ميخائيل، رسول الله. ورأيتُ مركبة كالريح وعجلاتها نارية، واختُطفتُ إلى فردوس البر، ورأيتُ الرب جالساً وكان وجهه ناراً متوهجة لا تُطاق. وكانت ألوف كثيرة من الملائكة عن يمين تلك المركبة ويسارها».",
      "verse": 3
    },
    {
      "chapter": 26,
      "text_ar": "ولما رأيتُ هذا، ارتبكتُ وأخذني الرعب وسجدتُ أمام",
      "verse": 1
    },
    {
      "chapter": 26,
      "text_ar": "الله ووجهي إلى الأرض. وقال لي الله: «هوذا أنت تموت، لأنك تعديتَ وصية الله، إذ سمعتَ لصوت امرأتك بالأحرى، التي أسلمتها إلى سلطانك لتتمسك بإرادتك. ومع ذلك فقد أصغيتَ إليها وتجاهلتَ كلامي».",
      "verse": 2
    }
  ],
  "book_code": "TADAM"
}
